// Workspace A: custom Blink
void setup() { pinMode(LED_BUILTIN, OUTPUT); }
void loop() { digitalWrite(LED_BUILTIN, HIGH); delay(173); digitalWrite(LED_BUILTIN, LOW); delay(173); }

// Workspace B: serial data
const int sensorValue = 427;
void setup() { Serial.begin(9600); pinMode(8, OUTPUT); }
void loop() { Serial.println(sensorValue); digitalWrite(8, HIGH); delay(53); }
